```python
import boto3
import os
from typing import List, Dict, Any

def extract_document_layout(file_path: str) -> List[Dict[str, Any]]:
    """
    Extracts text, tables, and form data from a document using Amazon Textract.

    This function requires AWS credentials to be configured in the environment
    (e.g., via AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and AWS_REGION).

    :param file_path: The local path to the document file (PDF, PNG, JPG).
    :return: A list of dictionaries, where each dictionary represents a
             detected layout element (e.g., a line, a table, a form field).
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found at {file_path}")

    # Provider-identifying signal: boto3.client for 'textract'
    # This establishes a session with the Amazon Textract service.
    # The region can be changed as needed.
    textract_client = boto3.client("textract")

    with open(file_path, "rb") as document_file:
        document_bytes = document_file.read()

    # Call Textract's AnalyzeDocument API to extract text, forms, and tables
    response = textract_client.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=["TABLES", "FORMS"]
    )

    blocks = response.get("Blocks", [])
    if not blocks:
        return []

    block_map = {block["Id"]: block for block in blocks}

    def get_text_from_relationships(block: Dict, b_map: Dict) -> str:
        """Helper to extract concatenated text from child WORD blocks."""
        text = ""
        if "Relationships" in block:
            for relationship in block["Relationships"]:
                if relationship["Type"] == "CHILD":
                    for child_id in relationship["Ids"]:
                        child_block = b_map.get(child_id)
                        if child_block and child_block["BlockType"] == "WORD":
                            text += child_block.get("Text", "") + " "
        return text.strip()

    extracted_elements = []
    for block in blocks:
        block_type = block["BlockType"]

        if block_type == "LINE":
            element = {
                "type": "LINE",
                "text": block.get("Text", ""),
                "geometry": block.get("Geometry"),
            }
            extracted_elements.append(element)

        elif block_type == "TABLE":
            table_element = {
                "type": "TABLE",
                "geometry": block.get("Geometry"),
                "cells": []
            }
            if "Relationships" in block:
                for rel in block["Relationships"]:
                    if rel["Type"] == "CHILD":
                        for cell_id in rel["Ids"]:
                            cell = block_map.get(cell_id)
                            if not cell:
                                continue
                            cell_text = get_text_from_relationships(cell, block_map)
                            table_element["cells"].append({
                                "row": cell.get("RowIndex"),
                                "column": cell.get("ColumnIndex"),
                                "text": cell_text,
                                "geometry": cell.get("Geometry"),
                            })
            extracted_elements.append(table_element)

        elif block_type == "KEY_VALUE_SET" and "KEY" in block.get("EntityTypes", []):
            key_text = get_text_from_relationships(block, block_map)
            value_text = ""
            if "Relationships" in block:
                for rel in block["Relationships"]:
                    if rel["Type"] == "VALUE":
                        for value_id in rel["Ids"]:
                            value_block = block_map.get(value_id)
                            if value_block:
                                value_text = get_text_from_relationships(value_block, block_map)

            form_element = {
                "type": "FORM_FIELD",
                "key": {"text": key_text, "geometry": block.get("Geometry")},
                "value": {"text": value_text, "geometry": value_block.get("Geometry") if value_block else None}
            }
            extracted_elements.append(form_element)

    return extracted_elements
